findings.codeql_raw_query:
/**
 * @name Code injection via eval in CLI
 * @description Detects flow from sys.argv to eval
 * @kind path-problem
 * @problem.severity error
 * @id py/cli-eval-injection
 * @tags security
 *       external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module EvalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
     source = API::moduleImport("sys").getMember("argv").asSource()
  }

  predicate isSink(DataFlow::Node sink) {
    sink = API::builtin("eval").getACall().getArg(0)
  }
}

module EvalFlow = TaintTracking::Global<EvalConfig>;
import EvalFlow::PathGraph

from EvalFlow::PathNode source, EvalFlow::PathNode sink
where EvalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Eval called with CLI data from $@.", source.getNode(), "sys.argv"
